        DB::table('aboutuses')->insert([
            ['id' => 1, 'created_at' => '2021-04-23 02:11:14', 'updated_at' => '2026-06-28 14:02:03', 'titre' => 'الرؤية و المهمة', 'description' => null, 'structured_description' => '{"sections": [{"id": "legacy-paragraph-1", "type": "paragraph", "content": "رؤية جمعية بلسم:  ==\\r\\n---\\r\\n\\r\\nأن تصبح منظمة عالمية لمساعدة الناس على تحسين حياتهم في مجالات التوحد، مجتمعياً، والانتقال نحو مجتمع قوي.  \\r\\n\\r\\n--- \\r\\n مهمة جمعية بلسم:  ==\\r\\n ---\\r\\n\\r\\nالمساهمة في تحسين حياة ذوي التوحد، عن طريق خدماتنا وبرامجنا التي يجب أن تساعد الناس اليوم، ... من أسرة طفل توحدي تم تشخيصه حديثًا ولا يعرف إلى أين يتجه؟ ... إلى أحد أفراد عائلة شخص بالغ شُخص باضطراب طيف التوحد، يجد نفسه في وضع مقدم الرعاية الأساسي ... يمكن لجمعية لبلسم المساعدة"}]}', 'about_image' => '1619274783.jpg', 'status' => 1],
            ['id' => 2, 'created_at' => '2021-04-24 03:52:58', 'updated_at' => '2021-04-27 21:59:24', 'titre' => 'من نحن', 'description' => null, 'structured_description' => '{"sections": [{"id": "legacy-paragraph-2", "type": "paragraph", "content": "---      فريق  بلسم هو مجموعة من أمهات و آباء لأطفال ذوي التوحد،  ===  ---\\r\\n أخذوا على عاتقهم مهمة المساهمة في تحسين حياة ذوي التوحد، عن طريق : الدعم، و الاحتضان، و التوجيه، و الارشاد، و التكوين، و تقديم الخدمات الشبه طبية، تحت إشراف مختصين في المجال.\\r\\n---\\r\\n    مهمة جمعية بلسم، هي المساهمة في تحسين حياة ذوي التوحد، === --- عن طريق خدماتنا وبرامجنا التي يجب أن تساعد الناس اليوم، ... من أسرة طفل توحدي تم تشخيصه حديثًا ولا يعرف إلى أين يتجه؟ ... إلى أحد أفراد عائلة شخص بالغ شُخص باضطراب طيف التوحد، يجد نفسه في وضع مقدم الرعاية الأساسي ... يمكن لجمعية لبلسم المساعدة.  \\r\\n\\r\\n --- === \\"بلسم\\" عضو بتحالف الجمعيات العاملة في إعاقة التوحد بالمغرب (CAM) === --- ، و هو تحالف يضم جمعيات بالمغرب تشتغل في مجال التوحد. كما يتكون التحالف من تحالفات جهوية تتوزع حسب التقسيم الجهوي للمملكة.  (https://www.collectifautisme.ma/) ---\\r\\n  تتعاون \\"بلسم\\" وتنسق مع المنظمات غير الحكومية، === --- الوطنية والدولية، والسلطات المحلية، لتوفر أفضل الخدمات لذوي التوحد. ---"}]}', 'about_image' => '1619274228.png', 'status' => -1],
            ['id' => 4, 'created_at' => '2021-04-24 06:11:07', 'updated_at' => '2021-04-24 14:52:45', 'titre' => 'أهدافنا', 'description' => null, 'structured_description' => '{"sections": [{"id": "legacy-paragraph-4", "type": "paragraph", "content": "--- \\r\\nتهدف الجمعية حسب قانونها الأساسي في المادة الخامسة إلى تقديم خدمات للأشخاص التوحديين وذويهم، وذلك ب: === ---\\r\\n\\r\\n---  استفادة الأطفال ذوي التوحد من تمدرس يمكنهم من الاندماج في المؤسسات التعليمية العمومية والخصوصية. \\r\\n***\\r\\n تقديم جميع أنواع الخدمات الطبية والشبه الطبية للأطفال والأشخاص التوحديين في حدود الإمكانيات المتوفرة لدى الجمعية. \\r\\n***\\r\\n تقديم خدمات تربوية، صحية، اجتماعية، رياضية، وتنظيم مخيمات تستجيب لمختلف حاجيات الأشخاص ذوي التوحد. \\r\\n***\\r\\n تمكين أسر الأشخاص ذوي التوحد من تكوينات تستجيب لتطلعاتهم من أجل تكفل أفضل بهم. \\r\\n***\\r\\n عقد شراكات مع المؤسسات الرسمية والخاصة والتعاون معها فيما له علاقة بمجال إفادة الأشخاص ذوي التوحد. \\r\\n---"}]}', 'about_image' => '1619275600.jpg', 'status' => 1],
